import { useRef } from 'react'
import { overlay } from '../../../config'
import useOverlay from '../../../hooks/useOverlay'
import LineChartIcon from '../../Icons/LineChartIcon/LineChartIcon'
import styles from './DashboardButton.module.css'

function DashboardButton() {
  const buttonRef = useRef(null)
  const { openOverlay } = useOverlay()
  
  const onClick = event => {
    navigator.vibrate?.(50)
    openOverlay(overlay.dashboard, buttonRef.current)
  }
  
  return (
    <button className={styles.dashboardButton} onClick={onClick} ref={buttonRef} type="button" aria-label="open dashboard">
      <LineChartIcon />
    </button>
  )
}

export default DashboardButton
